page Home "/" {
  meta title="Simulación de pelotas"

  state count = 0
  state frames = 0
  state paused = false

  ref box
  ref ctx
  ref balls
  ref raf

  fn rnd(a, b) {
    return a + Math.random() * (b - a)
  }

  fn newBall() {
    let r = 10
    let x = 0
    let y = 0
    for (let tries = 0; tries < 50; tries++) {
      x = rnd(r, 400 - r)
      y = rnd(r, 300 - r)
      let ok = true
      for b in balls ?? [] {
        if Math.hypot(b.x - x, b.y - y) < 2 * r {
          ok = false
          break
        }
      }
      if ok { break }
    }
    return { x: x, y: y, vx: rnd(-3, 3), vy: rnd(-3, 3), r: r, color: `hsl(${Math.floor(Math.random() * 360)}, 70%, 50%)` }
  }

  fn makeBalls(n) {
    balls = []
    for (let i = 0; i < n; i++) {
      balls.push(newBall())
    }
    count = balls.length
  }

  fn step() {
    for b in balls {
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let a = balls[i]
        let b = balls[j]
        let dx = b.x - a.x
        let dy = b.y - a.y
        let dist = Math.hypot(dx, dy)
        let minD = a.r + b.r
        if dist < minD {
          if dist == 0 {
            dx = 1
            dy = 0
            dist = 1
          }
          let nx = dx / dist
          let ny = dy / dist
          let approaching = (b.vx - a.vx) * dx + (b.vy - a.vy) * dy < 0
          if approaching {
            let tvx = a.vx
            let tvy = a.vy
            a.vx = b.vx
            a.vy = b.vy
            b.vx = tvx
            b.vy = tvy
          }
          let overlap = (minD - dist) / 2
          a.x -= nx * overlap
          a.y -= ny * overlap
          b.x += nx * overlap
          b.y += ny * overlap
        }
      }
    }
    for b in balls {
      if b.x < b.r {
        b.x = b.r
        b.vx = Math.abs(b.vx)
      }
      if b.x > 400 - b.r {
        b.x = 400 - b.r
        b.vx = -Math.abs(b.vx)
      }
      if b.y < b.r {
        b.y = b.r
        b.vy = Math.abs(b.vy)
      }
      if b.y > 300 - b.r {
        b.y = 300 - b.r
        b.vy = -Math.abs(b.vy)
      }
    }
  }

  fn draw() {
    ctx.clearRect(0, 0, 400, 300)
    for b in balls {
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fillStyle = b.color
      ctx.fill()
    }
  }

  fn tick() {
    step()
    draw()
    frames++
    raf = requestAnimationFrame(tick)
  }

  fn start() {
    cancelAnimationFrame(raf)
    raf = requestAnimationFrame(tick)
  }

  fn toggle() {
    if paused {
      paused = false
      start()
    } else {
      paused = true
      cancelAnimationFrame(raf)
    }
  }

  fn add() {
    balls.push(newBall())
    count = balls.length
    if paused { draw() }
  }

  fn reset() {
    makeBalls(5)
    frames = 0
    draw()
  }

  mount {
    ctx = box.getContext("2d")
    makeBalls(5)
    frames = 0
    draw()
    start()
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 align=center {
    title "Simulación de pelotas" tag=h1
    canvas ref=box id="sim" width=400 height=300 style="border: 1px solid #ccc; background: #fafafa"
    row gap=2 {
      button "Agregar" primary -> add()
      button (paused ? "Reanudar" : "Pausar") -> toggle()
      button "Reiniciar" -> reset()
    }
    row gap=4 {
      text `Pelotas: ${count}` bold
      text `Cuadros: ${frames}` muted
    }
  }
}

page Home "/" {
  state count = 0
  state frames = 0
  state paused = false
  ref box
  ref balls
  ref raf

  fn makeBall() {
    let r = 10
    return {
      x: r + Math.random() * (400 - 2 * r),
      y: r + Math.random() * (300 - 2 * r),
      vx: (Math.random() * 2 - 1) * 3,
      vy: (Math.random() * 2 - 1) * 3,
      r: r
    }
  }

  fn clamp(b) {
    if b.x < b.r {
      b.x = b.r
      b.vx = Math.abs(b.vx)
    }
    if b.x > 400 - b.r {
      b.x = 400 - b.r
      b.vx = -Math.abs(b.vx)
    }
    if b.y < b.r {
      b.y = b.r
      b.vy = Math.abs(b.vy)
    }
    if b.y > 300 - b.r {
      b.y = 300 - b.r
      b.vy = -Math.abs(b.vy)
    }
  }

  fn update() {
    for b in balls {
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      clamp(b)
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let a = balls[i]
        let c = balls[j]
        let dx = c.x - a.x
        let dy = c.y - a.y
        let dist = Math.sqrt(dx * dx + dy * dy)
        let minD = a.r + c.r
        if dist < minD {
          if dist == 0 {
            dx = 1
            dy = 0
            dist = 1
          }
          let approaching = (c.vx - a.vx) * dx + (c.vy - a.vy) * dy < 0
          if approaching {
            let tx = a.vx
            let ty = a.vy
            a.vx = c.vx
            a.vy = c.vy
            c.vx = tx
            c.vy = ty
          }
          let overlap = (minD - dist) / 2
          let nx = dx / dist
          let ny = dy / dist
          a.x -= nx * overlap
          a.y -= ny * overlap
          c.x += nx * overlap
          c.y += ny * overlap
          clamp(a)
          clamp(c)
        }
      }
    }
  }

  fn draw() {
    if !box { return }
    let ctx = box.getContext("2d")
    ctx.clearRect(0, 0, 400, 300)
    ctx.fillStyle = "#2563eb"
    for b in balls {
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn loop() {
    update()
    draw()
    frames++
    raf = requestAnimationFrame(loop)
  }

  fn reset() {
    let list = []
    for (let i = 0; i < 5; i++) {
      list.push(makeBall())
    }
    balls = list
    count = balls.length
    frames = 0
    draw()
  }

  fn addBall() {
    balls.push(makeBall())
    count = balls.length
    if paused {
      draw()
    }
  }

  fn toggle() {
    if paused {
      paused = false
      raf = requestAnimationFrame(loop)
    } else {
      paused = true
      cancelAnimationFrame(raf)
    }
  }

  mount {
    reset()
    raf = requestAnimationFrame(loop)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 align=center {
    title "Simulación de pelotas" tag=h1
    canvas ref=box id="sim" width=400 height=300 style="border: 1px solid #ccc"
    row gap=2 {
      button "Agregar" primary -> addBall()
      button (paused ? "Reanudar" : "Pausar") -> toggle()
      button "Reiniciar" -> reset()
    }
    row gap=4 {
      text `Pelotas: ${count}`
      text `Cuadros: ${frames}`
    }
  }
}
